bool8 TrainerClassUsesPool(u8 trainerClass, enum TrainerPoolCategory *outCategory)
{
    *outCategory = POOL_CATEGORY_STATIC;

    switch (trainerClass)
    {
        // Generic classes → use their named pool
        case TRAINER_CLASS_HIKER:
        case TRAINER_CLASS_COOLTRAINER:
        case TRAINER_CLASS_BLACK_BELT:
        case TRAINER_CLASS_BEAUTY:
        case TRAINER_CLASS_LADY:
        case TRAINER_CLASS_COLLECTOR:
        case TRAINER_CLASS_AROMA_LADY:
        case TRAINER_CLASS_SWIMMER_M:
        case TRAINER_CLASS_BIRD_KEEPER:
        case TRAINER_CLASS_POKEMANIAC:
        case TRAINER_CLASS_GUITARIST:
        case TRAINER_CLASS_EXPERT:
        case TRAINER_CLASS_HEX_MANIAC:
        case TRAINER_CLASS_INTERVIEWER:
        case TRAINER_CLASS_TUBER_F:
        case TRAINER_CLASS_TUBER_M:
        case TRAINER_CLASS_RICH_BOY:
        case TRAINER_CLASS_PKMN_BREEDER:
            *outCategory = POOL_CATEGORY_GENERIC;
            return TRUE;

        // Gym Leaders → custom per type
        case TRAINER_CLASS_LEADER:
            *outCategory = POOL_CATEGORY_GYM_LEADER;
            return TRUE;

        // Rival
        case TRAINER_CLASS_RIVAL:
            *outCategory = POOL_CATEGORY_RIVAL;
            return TRUE;

        // Elite Four
        case TRAINER_CLASS_ELITE_FOUR:
            *outCategory = POOL_CATEGORY_ELITE_FOUR;
            return TRUE;

        // Champion
        case TRAINER_CLASS_CHAMPION:
            *outCategory = POOL_CATEGORY_CHAMPION;
            return TRUE;

        // Villain admins & leaders
        case TRAINER_CLASS_AQUA_ADMIN:
        case TRAINER_CLASS_MAGMA_ADMIN:
            *outCategory = POOL_CATEGORY_VILLAIN_ADMIN;
            return TRUE;

        case TRAINER_CLASS_AQUA_LEADER:
        case TRAINER_CLASS_MAGMA_LEADER:
            *outCategory = POOL_CATEGORY_VILLAIN_LEADER;
            return TRUE;

        default:
            return TRUE;  // Enable pools for ALL classes by default
    }
}

