// ─────────────────────────────────────────────────────────────
// SPECIAL TRAINER PARTY GENERATION (5 from pool + shiny Ace)
// ─────────────────────────────────────────────────────────────
void GenerateSpecialTrainerParty(struct Trainer *trainer, const TrainerMonLine *pool, u16 aceSpecies)
{
    if (!trainer)
        return;
        
    if (!pool)
    {
        DebugPrintf("No pool - fallback to static\n");
        // Fallback to static party loading
        return;
    }

    // Always generate a full party (6 mons) when using pools
    u8 partySize = 6;
    
    DebugPrintf("Generating party of size %d (forced full for pools)\n", partySize);
    
    // Create a mutable copy of the party data
    struct TrainerMon *mutableParty = Alloc(sizeof(struct TrainerMon) * partySize);
    if (!mutableParty)
    {
        DebugPrintf("Failed to allocate mutable party\n");
        return;
    }
    
    // Initialize all slots to empty first
    for (u8 i = 0; i < partySize; i++)
    {
        memset(&mutableParty[i], 0, sizeof(struct TrainerMon));
    }

    u8 cap = GetCurrentLevelCap();  // Hoenn-based level cap scaling
    // u8 badges = 8; // TODO: Use GetBadgeCount()

    u8 slot = 0;
    
    // Simple EV spread
    // static const u8 simpleEVs[] = {252, 252, 0, 0, 0, 4};

    // Simplified pool generation - just pick first few entries for now
    const TrainerMonLine *line = pool;
    while (slot < partySize - 1 && line->weight > 0 && line->species[0] != SPECIES_NONE)
    {
        u8 stage = 0;
        for (u8 s = 1; s < MAX_EVO_STAGES; s++)
    {
        if (line->species[s] == SPECIES_NONE)
            break;
        if (cap >= line->min_level[s] && GetBadgeCount() >= line->min_badges[s])
            stage = s;
        else
            break;
    }
        u16 species = line->species[stage];
        u8 level = cap - (Random() % 9);
        if (level < 5) level = 5;

        mutableParty[slot].species = species;
        mutableParty[slot].lvl = cap;  // BRUTAL MODE: Max level for all Pokemon
        mutableParty[slot].iv = 31;  // Perfect IVs for brutal difficulty
        mutableParty[slot].nature = line->preferred_nature;
        mutableParty[slot].heldItem = ITEM_SITRUS_BERRY;  // BRUTAL MODE: All Pokemon have healing items
        mutableParty[slot].isShiny = FALSE;
        
        // BRUTAL MODE: Competitive EV spreads
        mutableParty[slot].ev = (u8[]){252, 252, 0, 0, 0, 4};
        
        // Initialize moves to empty
        for (u8 m = 0; m < MAX_MON_MOVES; m++)
        {
            mutableParty[slot].moves[m] = MOVE_NONE;
        }

        slot++;
        line++;
        
        DebugPrintf("Added species %d level %d\n", species, level);
        
        if (slot >= partySize - 1) break;
    }

    // Last slot = Shiny Ace (if we have an ace species), or 6th from pool to avoid species 0
    {
        u8 aceSlot = partySize - 1;
        if (aceSpecies != SPECIES_NONE && partySize > 1)
        {
            mutableParty[aceSlot].species = aceSpecies;
            mutableParty[aceSlot].lvl = cap;  // BRUTAL MODE: Max level ace
            mutableParty[aceSlot].iv = 31;     // Perfect IVs
            mutableParty[aceSlot].nature = NATURE_ADAMANT;  // BRUTAL MODE: Aggressive nature
            mutableParty[aceSlot].heldItem = ITEM_LEFTOVERS;  // BRUTAL MODE: Best healing item
            mutableParty[aceSlot].isShiny = TRUE;  // Always shiny for intimidation
            mutableParty[aceSlot].ev = (u8[]){252, 252, 0, 0, 0, 4};
            for (u8 m = 0; m < MAX_MON_MOVES; m++)
                mutableParty[aceSlot].moves[m] = MOVE_NONE;
            DebugPrintf("Added ace species %d level %d (shiny)\n", aceSpecies, cap);
        }
        else if (line->weight > 0 && line->species[0] != SPECIES_NONE)
        {
            // No ace specified: fill last slot from pool so we never leave slot 5 as species 0
            u8 stage = 0;
        for (u8 s = 1; s < MAX_EVO_STAGES; s++)
        {
            if (line->species[s] == SPECIES_NONE)
                break;
            if (cap >= line->min_level[s] && GetBadgeCount() >= line->min_badges[s])
                stage = s;
            else
                break;
        }
            mutableParty[aceSlot].species = line->species[stage];
            mutableParty[aceSlot].lvl = cap;
            mutableParty[aceSlot].iv = 31;
            mutableParty[aceSlot].nature = line->preferred_nature;
            mutableParty[aceSlot].heldItem = ITEM_SITRUS_BERRY;
            mutableParty[aceSlot].isShiny = FALSE;
            mutableParty[aceSlot].ev = (u8[]){252, 252, 0, 0, 0, 4};
            for (u8 m = 0; m < MAX_MON_MOVES; m++)
                mutableParty[aceSlot].moves[m] = MOVE_NONE;
            DebugPrintf("Added 6th from pool species %d (no ace)\n", line->species[0]);
        }
    }

    // Copy back to trainer's actual party (commented out - trainer->party is read-only)
    // for (u8 i = 0; i < partySize; i++)
    // {
    //     trainer->party[i] = mutableParty[i];
    // }

    trainer->partySize = partySize;  // or trainer->partyCount if your struct uses that
    
    DebugPrintf("Copied %d mons to trainer->party\n", partySize);
    DebugPrintf("trainer->party[0].species after copy: %d\n", trainer->party[0].species);
    DebugPrintf("After generation:\n");
    DebugPrintf("trainer->party pointer: %p\n", trainer->party);
    DebugPrintf("trainer->party[0].species: %d\n", trainer->party[0].species);
    DebugPrintf("trainer->party[5].species (Ace): %d\n", trainer->party[5].species);
    DebugPrintf("Returning from GenerateSpecialTrainerParty\n");
    
    // Convert TrainerMon → Pokemon and copy to gEnemyParty (battle system uses this)
    extern struct Pokemon gEnemyParty[PARTY_SIZE];
    
    for (u8 i = 0; i < partySize; i++)
    {
        struct Pokemon *dest = &gEnemyParty[i];
        struct TrainerMon *src = &mutableParty[i];

        // Basic mon creation
        CreateMon(dest, src->species, src->lvl, src->iv, 0, 0, OT_ID_RANDOM_NO_SHINY, 0);

        // Set nature, EVs, moves, item, shiny
        u8 tempNature = src->nature;
        SetMonData(dest, MON_DATA_HIDDEN_NATURE, &tempNature);
        SetMonData(dest, MON_DATA_IVS, src->ev);
        SetMonData(dest, MON_DATA_HELD_ITEM, &src->heldItem);

        // Shiny Ace
        if (src->isShiny)
        {
            u32 personality = GetMonData(dest, MON_DATA_PERSONALITY);
                personality |= (1 << 31);  // force shiny bit (adjust if your shiny system is different)
                SetMonData(dest, MON_DATA_PERSONALITY, &personality);
        }

        // Moves (you probably already have this helper)
        for (u8 m = 0; m < MAX_MON_MOVES; m++)
        {
            if (src->moves[m] != MOVE_NONE)
            {
                SetMonMoveSlot(dest, src->moves[m], m);
            }
        }
    }

    DebugPrintf("Copied %d mons to gEnemyParty\n", partySize);
    DebugPrintf("gEnemyParty[0].species after copy: %d\n", GetMonData(&gEnemyParty[0], MON_DATA_SPECIES));
}

// ─────────────────────────────────────────────────────────────
// SPECIAL POOL SELECTOR FOR IMPORTANT TRAINERS (LEGACY)
// ─────────────────────────────────────────────────────────────
const TrainerMonLine *GetSpecialPoolForTrainer(u16 trainerId)
{
    switch (trainerId)
    {
        case TRAINER_ROXANNE_1: return gRoxannePool;
        case TRAINER_BRAWLY_1: return gBrawlyPool;
        case TRAINER_WATTSON_1: return gWatsonPool;
        case TRAINER_FLANNERY_1: return gFlanneryPool;
        case TRAINER_NORMAN_1: return gNormanPool;
        case TRAINER_WINONA_1: return gWinonaPool;
        case TRAINER_TATE_AND_LIZA_1: return gTateLizaPool;
        case TRAINER_JUAN_1: return gJuanPool;
        case TRAINER_WALLACE: return gWallacePool;
        case TRAINER_STEVEN: return gStevenPool;
        // Add more for rematches (_2, _3, etc.) or other trainers
        default:
            DebugPrintf("No special pool for ID %d\n", trainerId);
            return NULL;
    }
}

// ─────────────────────────────────────────────────────────────
// DYNAMIC AI SYSTEM - Type-aware and difficulty scaling
// ─────────────────────────────────────────────────────────────

// Apply dynamic AI to trainer
void ApplyDynamicAIToTrainer(struct Trainer *trainer, struct Pokemon *generatedParty, u8 partySize)
{
    if (!trainer || !generatedParty || partySize == 0)
        return;
    
    // BRUTAL MODE: Every trainer gets maximum AI intelligence
    u64 brutalAIFlags = AI_FLAG_SMART_TRAINER | AI_FLAG_PREDICTION | AI_FLAG_OMNISCIENT;
    brutalAIFlags |= AI_FLAG_SMART_SWITCHING | AI_FLAG_SMART_MON_CHOICES | AI_FLAG_SMART_TERA;
    brutalAIFlags |= AI_FLAG_CHECK_BAD_MOVE | AI_FLAG_TRY_TO_FAINT | AI_FLAG_CHECK_VIABILITY;
    brutalAIFlags |= AI_FLAG_PP_STALL_PREVENTION;
    
    // Add prediction capabilities for maximum challenge
    brutalAIFlags |= AI_FLAG_PREDICT_SWITCH | AI_FLAG_PREDICT_INCOMING_MON | AI_FLAG_PREDICT_MOVE;
    
    // Add strategic assumptions
    brutalAIFlags |= AI_FLAG_ASSUME_STAB | AI_FLAG_ASSUME_STATUS_MOVES | AI_FLAG_WEIGH_ABILITY_PREDICTION;
    
    // Update trainer's AI flags to maximum brutality
    struct Trainer *mutableTrainer = (struct Trainer *)trainer;
    mutableTrainer->aiFlags = brutalAIFlags;
    
    DebugPrintf("Applied BRUTAL AI flags: %08X%08X for trainer class %d\n", 
               (u32)(brutalAIFlags >> 32), (u32)(brutalAIFlags), trainer->trainerClass);
    DebugPrintf("This trainer will now fight with ELITE intelligence!\n");
}
